def norm(s):
 mi=min(r for r,c in s); mj=min(c for r,c in s); return frozenset((r-mi,c-mj) for r,c in s)
def vars(s):
 out=[]
 for f in [lambda x:x,lambda x:(x[0],-x[1])]:
  t={f(p) for p in s}
  for _ in range(4):
   out.append(norm(t));t={(c,-r) for r,c in t}
 return set(out)
for name,s in [('A',A),('B',B),('C',C)]: print(name,norm(s),len(vars(s)))
